const body = $('Webhook').first().json.body;
const raw = String(body.query || "").trim();
const f = body.filters || {};
let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}

if (!raw || raw.startsWith("/") || o.intent === "help") {
  return [{ json: { mode: "help", source: "text", query: "", user_ingredients: [], uncertain: [],
    max_minutes: null, max_calories: null, vegetarian: false, cuisine: null, min_protein: null } }];
}

const items = [...new Set((Array.isArray(o.items) ? o.items : [])
  .map(x => String(x).toLowerCase().trim()).filter(Boolean))];
// UI filters take priority; LLM-extracted filters are the fallback
const maxMin = f.max_minutes || (Number(o.max_minutes) > 0 ? Number(o.max_minutes) : null);
const maxCal = f.max_kcal || (Number(o.max_calories) > 0 ? Number(o.max_calories) : null);
const veg = f.vegetarian === true || o.vegetarian === true;
const cuisine = f.cuisine || null;
const min_protein = f.min_protein_g || null;

if (o.intent === "ingredients" && items.length) {
  return [{ json: { mode: "ingredients", source: "text", query: "Ingredients: " + items.join(", "), title_query: "",
    user_ingredients: items, uncertain: [], max_minutes: maxMin, max_calories: maxCal, vegetarian: veg,
    cuisine, min_protein } }];
}

const dish = ((o.dish && String(o.dish).trim()) || raw).toLowerCase();
return [{ json: { mode: "text", source: "text", query: dish, title_query: dish, user_ingredients: [], uncertain: [],
  max_minutes: maxMin, max_calories: maxCal, vegetarian: veg, cuisine, min_protein } }];

const r=$input.first().json||{};
const p=r.parsed||null;
const doc=r.mode==='document';
const request={...r,vegetarian:r.vegetarian===true,max_minutes:Number(r.max_minutes)>0?Number(r.max_minutes):null,max_calories:Number(r.max_calories)>0?Number(r.max_calories):null,min_protein:Number(r.min_protein)>0?Number(r.min_protein):null};
const state={request,stage:doc?'chef':'search',search_attempts:0,chef_revisions:0,controller_turns:0,planner:{},chef:null,validator:null,selection:null,alternatives:[],search_query:request.query||'',feedback:'',final_json:null,error:null,code:null};
if(doc){state.selection={id:null,payload:{name:p.title||p.title_en||'Recipe from your document',minutes:null,ingredients:p.ingredients||[],ingredient_lines:p.ingredients||[],steps:p.steps||[],document_complete:p.complete,servings:p.servings,recipe_time:p.time}};}
return [{json:state}];

const s=$input.first().json;
const turns=(s.controller_turns||0)+1;
return [{json:{...s,controller_turns:turns,stage:turns>8?'error':s.stage,error:turns>8?'The workflow reached its maximum controlled loop count.':s.error,code:turns>8?'LOOP_LIMIT':s.code}}];

// Stage transitions are enforced by code, not delegated to a 3B LLM.
const s=$('Supervisor Context').last().json;
let planner={};try{planner=JSON.parse($json.message?.content||'{}')}catch(e){}
const q=String(planner.search_query||'').slice(0,230).trim();
return [{json:{...s,planner:{action:s.stage,search_query:q,reason:String(planner.reason||'').slice(0,180)}}}];

const s=$input.first().json, r=s.request;
let q=String(s.retry_query||s.planner?.search_query||s.search_query||r.query||'').trim();
if(!q)q=String(r.title_query||'').trim();
// Avoid accidentally losing the pantry through an overly creative supervisor rewrite.
if(r.mode==='ingredients'&&(r.user_ingredients||[]).length){q='recipe using '+r.user_ingredients.slice(0,s.search_attempts?5:12).join(', ')+(r.original_user_text?' for '+r.original_user_text.slice(0,60):'');}
return [{json:{...s,search_query:q.slice(0,600),search_attempts:(s.search_attempts||0)+1,retry_query:null}}];

const s=$('Prepare Search').last().json;
const vector=$json.embeddings?.[0];
if(!Array.isArray(vector)||!vector.length)throw Error('Ollama bge-m3 returned no embedding');
const r=s.request,must=[];
if(r.max_minutes!=null)must.push({key:'minutes',range:{lte:Number(r.max_minutes)}});
if(r.max_calories!=null)must.push({key:'calories_per_serving',range:{lte:Number(r.max_calories)}});
if(r.min_protein!=null)must.push({key:'protein_g',range:{gte:Number(r.min_protein)}});
// Cuisine and vegetarian are additionally checked against actual record content after retrieval.
// Do not rely on database vegetarian flags that have proven inconsistent.
const body={vector,limit:r.mode==='ingredients'?100:80,with_payload:true};
if(must.length)body.filter={must};
return [{json:{...s,qdrant_body:body}}];

const s=$('Build Qdrant Request').last().json, r=s.request;
const all=Array.isArray($json.result)?$json.result:[];
const generic=new Set(['for','the','recipe','recipes','dinner','lunch','breakfast','what','should','cook','make','want','vegetarian','vegan','quick','easy','please','with','and','food','meal','in','under']);
const meat=/\b(chicken|beef|pork|lamb|veal|bacon|ham|sausage|salami|fish|tuna|salmon|anchov\w*|shrimp|prawn|gelatin|lard|meat|turkey|duck|pepperoni|prosciutto|oyster|clam|crab|lobster)\b/i;
const norm=v=>String(v??'').toLowerCase().replace(/[^a-z ]/g,' ').replace(/\s+/g,' ').trim();
const stem=w=>w.endsWith('ies')?w.slice(0,-3)+'y':w.endsWith('s')&&!w.endsWith('ss')&&w.length>3?w.slice(0,-1):w;
const tok=v=>norm(v).split(' ').filter(Boolean).map(stem);
const overlap=(a,b)=>a.length&&b.length&&(a.every(x=>b.includes(x))||b.every(x=>a.includes(x)));
const available=(r.user_ingredients||[]).map(tok).filter(a=>a.length);
const titleTokens=tok(r.title_query||'').filter(x=>x.length>2&&!generic.has(x));
const pantry=new Set(['salt','water','pepper','olive oil','vegetable oil','oil','ice','sugar'].map(x=>tok(x).join(' ')));
const needIngredients=(r.mode==='ingredients'||String(r.source).includes('photo'))&&available.length>0;
let eligible=[];
for(const hit of all){
 const p=hit.payload||{};if(!p.name||!Array.isArray(p.ingredients)||!Array.isArray(p.steps)||!p.steps.length)continue;
 if(r.vegetarian&&(meat.test(String(p.name))||p.ingredients.some(x=>meat.test(String(x)))))continue;
 if(r.max_minutes!=null&&!(Number(p.minutes)>0&&Number(p.minutes)<=r.max_minutes))continue;
 if(r.max_calories!=null&&!(p.calories_per_serving!=null&&Number(p.calories_per_serving)<=r.max_calories))continue;
 if(r.min_protein!=null&&!(p.protein_g!=null&&Number(p.protein_g)>=r.min_protein))continue;
 if(r.cuisine&&norm(p.cuisine_type)!==norm(r.cuisine))continue;
 const needed=p.ingredients.filter(x=>!pantry.has(tok(x).join(' ')));
 const have=needIngredients?needed.filter(x=>available.some(u=>overlap(tok(x),u))):[];
 const missing=needIngredients?needed.filter(x=>!available.some(u=>overlap(tok(x),u))):[];
 // Photo request requires multiple real overlaps, not merely similarity of names.
 const minHave=Math.min(needIngredients&&available.length>=5?3:needIngredients&&available.length>=2?2:1,available.length);
 if(needIngredients&&have.length<minHave)continue;
 let titleMatch=titleTokens.length?titleTokens.filter(t=>tok(p.name).includes(t)).length/titleTokens.length:0;
 const text=norm(r.original_user_text||r.query||'');
 const dinner=/\b(dinner|lunch|meal|supper)\b/.test(text);
 const drink=/\b(juice|smoothie|cocktail|lemonade|drink|tea|coffee)\b/.test(norm(p.name));
 const dessert=/\b(cake|cookies|brownies|ice cream|pudding|dessert|cupcake)\b/.test(norm(p.name));
 if(dinner&&(drink||dessert))continue;
 const mealBonus=dinner?(/\b(stir fry|pasta|rice|soup|casserole|salad|vegetable|chili|potato|roast|curry)\b/.test(norm(p.name))?1:0):0;
 const score=(needIngredients?(have.length*2+8*have.length/Math.max(1,needed.length)-missing.length*1.1):titleMatch*4)+(hit.score||0)*2+mealBonus;
 eligible.push({hit,have,missing,score});
}
eligible.sort((a,b)=>b.score-a.score);
if(eligible.length){
 const e=eligible[0], chosen={id:e.hit.id,payload:e.hit.payload,score:e.hit.score};
 return [{json:{...s,stage:'chef',selection:chosen,have:e.have,missing:e.missing,
 alternatives:eligible.slice(1,3).map(x=>({name:x.hit.payload.name,minutes:x.hit.payload.minutes,missing:x.missing.length})),
 ranking:{count:eligible.length,match_count:e.have.length,requested_ingredients:available.length,quality_score:e.score},feedback:''}}];
}
if(s.search_attempts<2){
 const fallback=(r.user_ingredients||[]).length?'recipes with '+r.user_ingredients.slice(0,4).join(' '):('recipe '+String(r.title_query||r.query||'').slice(0,60));
 return [{json:{...s,stage:'search',retry_query:fallback,feedback:'No acceptable recipes in the first search. Try a different query without changing filters.'}}];
}
return [{json:{...s,stage:'error',code:'NO_MATCH',error:'No recipe meets the filters and ingredient requirements. Try a different query or relax a preference.'}}];

const s=$('Route Stage').last(1).json;
let p={};try{p=JSON.parse($json.message?.content||'{}')}catch(e){}
const clean=x=>String(x||'').replace(/[*_`#\[\]]/g,'').replace(/\s+/g,' ').trim().slice(0,200);
const allowed=new Set((s.request.mode==='ingredients'?s.missing||[]:[]).map(x=>clean(x).toLowerCase()));
const seen=new Set();let subs=[];
for(const x of (Array.isArray(p.substitutions)?p.substitutions:[])){
 if(!x||typeof x!=='object'||Array.isArray(x))continue;
 const missing=clean(x.missing),replace_with=clean(x.replace_with);
 if(!missing||!replace_with||!allowed.has(missing.toLowerCase())||seen.has(missing.toLowerCase()))continue;
 seen.add(missing.toLowerCase());subs.push({missing,replace_with});if(subs.length===2)break;
}
return [{json:{...s,stage:'validate',chef:{intro:clean(p.intro),tip:clean(p.tip),substitutions:subs},feedback:''}}];

const s=$('Route Stage').last(2).json;
let v={};try{v=JSON.parse($json.message?.content||'{}')}catch(e){}
const chef=s.chef||{intro:'',tip:'',substitutions:[]};
const issues=[];const p=s.selection?.payload;
const meat=/\b(chicken|beef|pork|lamb|veal|bacon|ham|sausage|salami|fish|tuna|salmon|anchov\w*|shrimp|prawn|gelatin|lard|meat|turkey|duck|pepperoni|crab)\b/i;
// Recheck all hard constraints before any response can be approved.
if(!p||!Array.isArray(p.ingredients)||!Array.isArray(p.steps))issues.push('Recipe was not grounded in an actual record/document');
if(s.request.vegetarian&&p&&(p.ingredients.some(x=>meat.test(String(x)))||meat.test(p.name)))issues.push('Not vegetarian');
if(s.request.max_minutes!=null&&s.request.mode!=='document'&&!(Number(p?.minutes)>0&&Number(p.minutes)<=s.request.max_minutes))issues.push('Time filter failed');
if(s.request.max_calories!=null&&s.request.mode!=='document'&&!(p?.calories_per_serving!=null&&Number(p.calories_per_serving)<=s.request.max_calories))issues.push('Calories filter failed');
if(s.request.min_protein!=null&&s.request.mode!=='document'&&!(p?.protein_g!=null&&Number(p.protein_g)>=s.request.min_protein))issues.push('Protein filter failed');
if(s.request.cuisine&&s.request.mode!=='document'&&String(p?.cuisine_type||'').toLowerCase()!==String(s.request.cuisine).toLowerCase())issues.push('Cuisine filter failed');
const checked=typeof v.intro_ok==='boolean'&&typeof v.tip_ok==='boolean'&&Array.isArray(v.substitutions);
if(!checked&&(s.chef_revisions||0)>=1)return [{json:{...s,stage:'error',code:'VALIDATOR_BAD_OUTPUT',error:'The independent validator did not return valid review JSON after retry.'}}];
const introOk=checked?v.intro_ok:false, tipOk=checked?v.tip_ok:false;
const subs=(chef.substitutions||[]).filter((x,i)=>checked&&v.substitutions[i]===true);
if(issues.length)return [{json:{...s,stage:'error',code:'RECIPE_FAILED_HARD_VALIDATION',error:'Selected recipe failed mandatory constraints.',issues}}];
const failed=(!!chef.intro&&!introOk)||(!!chef.tip&&!tipOk)||(chef.substitutions||[]).length!==subs.length;
if(failed&&(s.chef_revisions||0)<1){
 const feedback=['Revise only the optional Chef text, keep the selected recipe unchanged.',!introOk?'Intro was rejected: do not invent ingredients or methods.':'',!tipOk?'Tip was rejected: use the recipe steps exactly.':'',(chef.substitutions||[]).length!==subs.length?'Substitutions rejected: remove or replace them accurately.':'',...(Array.isArray(v.issues)?v.issues.slice(0,4):[])].filter(Boolean).join(' ');
 return [{json:{...s,stage:'chef',chef_revisions:(s.chef_revisions||0)+1,feedback,validator:v}}];
}
// After one revision, omit any unapproved commentary, but retain the grounded recipe.
const intro=introOk?chef.intro:'',tip=tipOk?chef.tip:'';
const rawSteps=Array.isArray(p.steps)?p.steps:[],rawIngs=Array.isArray(p.ingredient_lines)&&p.ingredient_lines.length?p.ingredient_lines:p.ingredients;
const strings=a=>(Array.isArray(a)?a:[]).map(x=>String(x)).filter(Boolean);
const final={name:String(p.name),minutes:Number(p.minutes)>0?Number(p.minutes):null,recipe_time:p.recipe_time||null,servings:p.servings||null,
 ingredients:strings(rawIngs).slice(0,45),steps:strings(rawSteps).slice(0,35),calories_per_serving:p.calories_per_serving??null,
 protein_g:p.protein_g??null,carbs_g:p.carbs_g??null,fat_g:p.fat_g??null,
 cuisine_type:p.cuisine_type||null,image_url:p.image_url||null,
 intro,tip,chef_note:[intro,tip].filter(Boolean).join(' '),substitutions:subs,
 have:s.have||[],missing:s.missing||[],user_ingredients:s.request.user_ingredients||[],uncertain:s.request.uncertain||[],
 alternatives:s.alternatives||[],mode:s.request.mode,source:s.request.source||'',chosen_id:s.selection?.id??null,
 applied_filters:{vegetarian:!!s.request.vegetarian,max_minutes:s.request.max_minutes,max_kcal:s.request.max_calories,min_protein_g:s.request.min_protein,cuisine:s.request.cuisine||null},
 agentic_review:{status:'approved',architecture:'explicit_controller',validator_checked:checked,chef_revisions:s.chef_revisions||0,commentary_filtered:!introOk||!tipOk||(chef.substitutions||[]).length!==subs.length},
 document_complete:p.document_complete??null};
return [{json:{...s,stage:'done',validator:v,final_json:final}}];

const s=$input.first().json||{};
if(s.stage==='done'&&s.final_json&&s.final_json.agentic_review?.status==='approved')return [{json:s.final_json}];
if(s.error)return [{json:{error:String(s.error),code:String(s.code||'NO_MATCH'),issues:s.issues||[],filters:s.request?{vegetarian:s.request.vegetarian,max_minutes:s.request.max_minutes,max_kcal:s.request.max_calories,cuisine:s.request.cuisine}:undefined}}];
return [{json:{error:'No validated recipe could be produced.',code:'NOT_VALIDATED'}}];
